import{_ as i,a0 as c,w as _,s as g,ao as s,I as a,x as t,a1 as o,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"如何使用Aptik来备份和恢复Ubuntu中的Apps和PPAs | LCTT x X-CMD","titleTemplate":false,"description":"如何使用Aptik来备份和恢复Ubuntu中的Apps和PPAs | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用Aptik来备份和恢复Ubuntu中的Apps和PPAs | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用Aptik来备份和恢复Ubuntu中的Apps和PPAs | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20100105 How to Backup and Restore Your Apps and PPAs in Ubuntu Using Aptik","title":"如何使用Aptik来备份和恢复Ubuntu中的Apps和PPAs","tag":"201501","desc":""},"relativePath":"201501/20100105 How to Backup and Restore Your Apps and PPAs in Ubuntu Using Aptik.md","filePath":"[post].md"}'),d={name:"201501/20100105 How to Backup and Restore Your Apps and PPAs in Ubuntu Using Aptik.md"};function r(u,p,l,k,m,w){const e=c("Link");return _(),g("div",null,[p[14]||(p[14]=s(`<h1 id="如何使用aptik来备份和恢复ubuntu中的apps和ppas" tabindex="-1">如何使用Aptik来备份和恢复Ubuntu中的Apps和PPAs <a class="header-anchor" href="#如何使用aptik来备份和恢复ubuntu中的apps和ppas" aria-label="Permalink to “如何使用Aptik来备份和恢复Ubuntu中的Apps和PPAs”">​</a></h1><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x300x00_lead_image_aptik.png.pagespeed.ic.n3TJwp8YK_.png" alt="00_lead_image_aptik"></p><p>当你想重装Ubuntu或者仅仅是想安装它的一个新版本的时候，如果有个便捷的方法来重新安装之前的应用并且重置其设置会很方便的。此时 <em>Aptik</em> 粉墨登场，它可以帮助你轻松实现。</p><p>Aptik（自动包备份和恢复）是一个可以用在Ubuntu，Linux Mint 和其他基于Debian以及Ubuntu的Linux发行版上的应用，它允许你将已经安装过的包括软件库、下载包、安装的应用和主题、用户设置在内的PPAs(个人软件包存档)备份到外部的U盘、网络存储或者类似于Dropbox的云服务上。</p><p>注意：当我们在此文章中说到输入某些东西的时候，如果被输入的内容被引号包裹，请不要将引号一起输入进去，除非我们有特殊说明。</p><p>想要安装Aptik，需要先添加其PPA。使用Ctrl + Alt + T快捷键打开一个新的终端窗口。输入以下文字，并按回车执行。</p><pre><code>sudo apt-add-repository –y ppa:teejee2008/ppa
</code></pre><p>当提示输入密码的时候，输入你的密码然后按回车。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x99x01_command_to_add_repository.png.pagespeed.ic.UfVC9QLj54.png" alt="01_command_to_add_repository"></p><p>在命令行提示符输入下边的命令，来确保资源库已经是最新版本。</p><pre><code>sudo apt-get update
</code></pre><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x252x02_update_command.png.pagespeed.ic.m9pvd88WNx.png" alt="02_update_command"></p><p>更新完毕后，你就完成了安装Aptik的准备工作。接下来输入以下命令并按回车：</p><pre><code>sudo apt-get install aptik
</code></pre><p>注意：你可能会看到一些有关于获取不到包更新的错误提示。不过别担心，如果这些提示看起来跟下边图片中类似的话，你的Aptik的安装就没有任何问题。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x416x03_command_to_install_aptik.png.pagespeed.ic.1jtHysRO9h.png" alt="03_command_to_install_aptik"></p><p>安装过程会被显示出来。其中一个被显示出来的消息会提到此次安装会使用掉多少磁盘空间，然后提示你是否要继续，按下“y”再按回车，继续安装。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x416x04_do_you_want_to_continue.png.pagespeed.ic.WQ15_UxK5Z.png" alt="04_do_you_want_to_continue"></p><p>当安装完成后，输入“Exit”并按回车或者按下左上角的“X”按钮，关闭终端窗口。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x416x05_closing_terminal_window.png.pagespeed.ic.9QoqwM7Mfr.png" alt="05_closing_terminal_window"></p><p>在正式运行Aptik前，你需要设置好备份目录到一个U盘、网络驱动器或者类似于Dropbox和Google Drive的云帐号上。这儿的例子中，我们使用的是Dropbox。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x243x06_creating_backup_folder.png.pagespeed.ic.7HzR9KwAfQ.png" alt="06_creating_backup_folder"></p><p>一旦设置好备份目录，点击启动栏上方的“Search”按钮。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x177x07_opening_search.png.pagespeed.ic.qvFiw6_sXa.png" alt="07_opening_search"></p><p>在搜索框中键入 “aptik”。结果会随着你的输入显示出来。当Aptik图标显示出来的时候，点击它打开应用。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x338x08_starting_aptik.png.pagespeed.ic.8fSl4tYR0n.png" alt="08_starting_aptik"></p><p>此时一个对话框会显示出来要求你输入密码。输入你的密码并按“OK”按钮。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x337x09_entering_password.png.pagespeed.ic.yanJYFyP1i.png" alt="09_entering_password"></p><p>Aptik的主窗口显示出来了。从“Backup Directory”下拉列表中选择“Other…”。这个操作允许你选择你已经建立好的备份目录。</p><p>注意：在下拉列表的右侧的 “Open” 按钮会在一个文件管理窗口中打开选择目录功能。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x533x10_selecting_other_for_directory.png.pagespeed.ic.dHbmYdAHYx.png" alt="10_selecting_other_for_directory"></p><p>在 “Backup Directory” 对话窗口中，定位到你的备份目录，然后按“Open”。</p><p>注意：如果此时你尚未建立备份目录或者想在备份目录中新建个子目录，你可以点“Create Folder”来新建目录。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x470x11_choosing_directory.png.pagespeed.ic.E-56x54cy9.png" alt="11_choosing_directory"></p><p>点击“Software Sources (PPAs).”右侧的 “Backup”来备份已安装的PPAs。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x13_selecting_all_software_sources.png.pagespeed.ic.zDFiDGfnks.png" alt="12_clicking_backup_software_sources"></p><p>然后“Backup Software Sources”对话窗口显示出来。已安装的包和对应的源（PPA）同时也显示出来了。选择你需要备份的源（PPAs），或者点“Select All”按钮选择所有源。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x13_selecting_all_software_sources.png.pagespeed.ic.zDFiDGfnks.png" alt="13_selecting_all_software_sources"></p><p>点击 “Backup” 开始备份。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x14_clicking_backup_for_all_software_sources.png.pagespeed.ic.n5h_KnQVZa.png" alt="14_clicking_backup_for_all_software_sources"></p><p>备份完成后，一个提示你备份完成的对话窗口会蹦出来。点击 “OK” 关掉。</p><p>一个名为“ppa.list”的文件出现在了备份目录中。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x15_closing_finished_dialog_software_sources.png.pagespeed.ic.V25-KgSXdY.png" alt="15_closing_finished_dialog_software_sources"></p><p>接下来，“Downloaded Packages (APT Cache)”的项目只对重装同样版本的Ubuntu有用处。它会备份下你系统缓存(/var/cache/apt/archives)中的包。如果你是升级系统的话，可以跳过这个条目，因为针对新系统的包会比现有系统缓存中的包更加新一些。</p><p>备份和恢复下载过的包，这可以在重装Ubuntu，并且重装包的时候节省时间和网络带宽。因为一旦你把这些包恢复到系统缓存中之后，他们可以重新被利用起来，这样下载过程就免了，包的安装会更加快捷。</p><p>如果你是重装相同版本的Ubuntu系统的话，点击 “Downloaded Packages (APT Cache)” 右侧的 “Backup” 按钮来备份系统缓存中的包。</p><p>注意：当你备份下载过的包的时候是没有二级对话框出现的。你系统缓存 (/var/cache/apt/archives) 中的包会被拷贝到备份目录下一个名叫 “archives” 的文件夹中，当整个过程完成后会出现一个对话框来告诉你备份已经完成。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x544x16_downloaded_packages_backed_up.png.pagespeed.ic.z8ysuwzQAK.png" alt="16_downloaded_packages_backed_up"></p><p>有一些包是你的Ubuntu发行版的一部分。因为安装Ubuntu系统的时候会自动安装它们，所以它们是不会被备份下来的。例如，火狐浏览器在Ubuntu和其他类似Linux发行版上都是默认被安装的，所以默认情况下，它不会被选择备份。</p>`,49)),a("p",null,[p[1]||(p[1]=t("像",-1)),o(e,{href:"http://www.howtogeek.com/203768"},{default:n(()=>[...p[0]||(p[0]=[t("package for the Chrome web browser",-1)])]),_:1}),p[2]||(p[2]=t("这种系统安装完后才安装的包或者包含 Aptik 的包会默认被选择上。这可以方便你备份这些后安装的包。",-1))]),p[15]||(p[15]=s('<p>按照需要选择想要备份的包。点击 “Software Selections” 右侧的 “Backup” 按钮备份顶层包。</p><p>注意：依赖包不会出现在这个备份中。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x18_clicking_backup_for_software_selections.png.pagespeed.ic.QI5D-IgnP_.png" alt="18_clicking_backup_for_software_selections"></p><p>备份目录中出现了两个名为 “packages.list” 和“packages-installed.list” 的文件，并且会弹出一个通知你备份完成的对话框。点击 ”OK“关闭它。</p><p>注意：“packages-installed.list”文件包含了所有的包，而 “packages.list” 在包含了所有包的前提下还指出了那些包被选择上了。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x19_software_selections_backed_up.png.pagespeed.ic.LVmgs6MKPL.png" alt="19_software_selections_backed_up"></p><p>要备份已安装软件的设置的话，点击 Aptik 主界面 “Application Settings” 右侧的 “Backup” 按钮，选择你要备份的设置，点击“Backup”。</p><p>注意：如果你要选择所有设置，点击“Select All”按钮。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x20_backing_up_app_settings.png.pagespeed.ic.7_kgU3Dj_m.png" alt="20_backing_up_app_settings"></p><p>被选择的配置文件统一被打包到一个名叫 “app-settings.tar.gz” 的文件中。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x21_zipping_settings_files.png.pagespeed.ic.dgoBj7egqv.png" alt="21_zipping_settings_files"></p><p>当打包完成后，打包后的文件被拷贝到备份目录下，另外一个备份成功的对话框出现。点击“OK”关掉。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x22_app_settings_backed_up.png.pagespeed.ic.Mb6utyLJ3W.png" alt="22_app_settings_backed_up"></p><p>放在 “/usr/share/themes” 目录的主题和放在 “/usr/share/icons” 目录的图标也可以备份。点击 “Themes and Icons” 右侧的 “Backup” 来进行此操作。“Backup Themes” 对话框默认选择了所有的主题和图标。你可以安装需要的、取消一些不要的，然后点击 “Backup” 进行备份。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x22a_backing_up_themes_and_icons.png.pagespeed.ic.KXa8W3YhyF.png" alt="22a_backing_up_themes_and_icons"></p><p>主题被打包拷贝到备份目录下的 “themes” 文件夹中，图标被打包拷贝到备份目录下的 “icons” 文件夹中。然后成功提示对话框出现，点击“OK”关闭它。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x22b_themes_and_icons_backed_up.png.pagespeed.ic.ejjRaymD39.png" alt="22b_themes_and_icons_backed_up"></p><p>一旦你完成了需要的备份，点击主界面左上角的“X”关闭 Aptik 。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x542x23_closing_aptik.png.pagespeed.ic.pNk9Vt3--l.png" alt="23_closing_aptik"></p><p>备份过的文件已存在于你选择的备份目录中，可以随时查看。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x374x24_backup_files_in_directory.png.pagespeed.ic.vwblOfN915.png" alt="24_backup_files_in_directory"></p><p>当你重装Ubuntu或者安装新版本的Ubuntu后，在新的系统中安装 Aptik 并且将备份好的文件置于新系统中使用。运行 Aptik，并使用每个条目的 “Restore” 按钮来恢复你的软件源、应用、包、设置、主题以及图标。</p><hr>',23)),a("p",null,[p[4]||(p[4]=t("via: ",-1)),o(e,{href:"http://www.howtogeek.com/206454/how-to-backup-and-restore-your-apps-and-ppas-in-ubuntu-using-aptik/"},{default:n(()=>[...p[3]||(p[3]=[t("http://www.howtogeek.com/206454/how-to-backup-and-restore-your-apps-and-ppas-in-ubuntu-using-aptik/",-1)])]),_:1})]),a("p",null,[p[7]||(p[7]=t("作者：Lori Kaufman 译者：",-1)),o(e,{href:"https://github.com/mr-ping"},{default:n(()=>[...p[5]||(p[5]=[t("Ping",-1)])]),_:1}),p[8]||(p[8]=t(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:n(()=>[...p[6]||(p[6]=[t("wxy",-1)])]),_:1})]),a("p",null,[p[11]||(p[11]=t("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...p[9]||(p[9]=[t("LCTT",-1)])]),_:1}),p[12]||(p[12]=t(" 原创翻译，",-1)),o(e,{href:"http://linux.cn/"},{default:n(()=>[...p[10]||(p[10]=[t("Linux中国",-1)])]),_:1}),p[13]||(p[13]=t(" 荣誉推出",-1))])])}const b=i(d,[["render",r]]);export{A as __pageData,b as default};
